class Transaction {
        private String type;
        private double amount;

        Transaction(String type, double amount) {
            this.type = type;
            this.amount = amount;
        }

        public String type() {
            return type;
        }

        public double amount() {
            return amount;
        }

        public boolean apply() {
            if (type.equals("DEPOSIT")) {
                balance += amount;
                successful++;
                return true;
            } else if (type.equals("WITHDRAW")) {
                if (balance - amount >= MINIMUM_BALANCE) {
                    balance -= amount;
                    successful++;
                    return true;
                } else {
                    rejected++;
                    return false;
                }
            }
            return false;
        }
    }

    void run(Transaction[] list) {
        for (int i = 0; i < list.length; i++) {
            boolean done = list[i].apply();
            if (done) {
                System.out.printf("%d %s %.2f Balance = %.2f%n",
                        i + 1, list[i].type(), list[i].amount(), balance);
            } else {
                System.out.printf("%d %s %.2f REJECTED Balance = %.2f%n",
                        i + 1, list[i].type(), list[i].amount(), balance);
            }
        }

        // Local class Summary declared inside run()
        class Summary {
            void printSummary() {
                System.out.printf("Final Balance = %.2f%n", balance);
                System.out.println("Successful = " + successful);
                System.out.println("Rejected = " + rejected);
            }
        }

        new Summary().printSummary();
    }
